import java.util.*;class InvalidAgeException extends Exception{InvalidAgeException(String m){super(m);}}class Student{String name;int age;Student(String n,int a){name=n;age=a;}void checkEligibility()throws InvalidAgeException{if(age<18)throw new InvalidAgeException("Student is not eligible because age is below 18.");System.out.println("Student is Eligible");}}public class Q10_Custom_Exception_Student_Eligibility{public static void main(String[]x){Scanner s=new Scanner(System.in);System.out.print("Enter name: ");String n=s.nextLine();System.out.print("Enter age: ");int a=s.nextInt();Student st=new Student(n,a);try{st.checkEligibility();}catch(InvalidAgeException e){System.out.println("Exception: "+e.getMessage());}s.close();}}
